import sys

def find_rotation_count(arr):
    if not arr:
        return 0

    low, high = 0, len(arr) - 1

    while low < high:
        if arr[low] < arr[high]:
            return low

        mid = (low + high) // 2

        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid

    return low

def main():
    line = sys.stdin.readline()
    if not line or not line.strip():
        print(0)
        return

    arr = list(map(int, line.split()))

    if not arr:
        print(0)
        return

    print(find_rotation_count(arr))

if __name__ == "__main__":
    main()
